166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        // Idempotent create: if this request repeats an already-seen 'Idempotency-Key', return the
170	        // owner created the first time (200) rather than creating a duplicate.
171	        String idempotencyKey = idempotencyKey();
172	        if (idempotencyKey != null) {
173	            Integer existingId = idempotentCreates.get(idempotencyKey);
174	            if (existingId != null) {
175	                Owner existing = this.clinicService.findOwnerById(existingId);
176	                if (existing != null) {
177	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
178	                }
179	            }
180	        }
181	        List<String> missingFields = new ArrayList<>();
182	        if (isBlank(ownerFieldsDto.getFirstName())) {
183	            missingFields.add("firstName");
184	        }
185	        if (isBlank(ownerFieldsDto.getLastName())) {
186	            missingFields.add("lastName");
187	        }
188	        // Normalize whichever address form was supplied and fold it into the DTO: the structured
189	        // 'addressLine1'/'addressLine2' win when a non-blank 'addressLine1' is present, otherwise the
190	        // flat 'address' is used. The composed value is stored back into 'address' so every reader of
191	        // the owner's address sees the effective (structured-or-flat) value.
192	        applyAddress(ownerFieldsDto);
193	        if (isBlank(ownerFieldsDto.getAddress())) {
194	            missingFields.add("address");
195	        }
196	        if (isBlank(ownerFieldsDto.getCity())) {
197	            missingFields.add("city");
198	        }
199	        if (isBlank(ownerFieldsDto.getTelephone())) {
200	            missingFields.add("telephone");
201	        }
202	        if (!missingFields.isEmpty()) {
203	            throw new MissingOwnerFieldsException(missingFields);
204	        }
205	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
206	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
207	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
208	            throw new FutureRegistrationDateException(
209	                "registrationDate must not be later than the server date");
210	        }
211	        LocalDate registrationDate = toBusinessDay(
212	            suppliedRegistrationDate != null
213	                ? suppliedRegistrationDate
214	                : LocalDate.now());
215	        long registeredOnDay = this.clinicService.findAllOwners().stream()
216	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
217	            .count();
218	        if (registeredOnDay >= 100) {
219	            throw new DailyRegistrationLimitException(
220	                "100 or more owners have already been registered today");
221	        }
222	        boolean bulkSignupWarning = registeredOnDay > 80;
223	        String city = ownerFieldsDto.getCity();
224	        long ownersInCity = this.clinicService.findAllOwners().stream()
225	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
226	            .count();
227	        if (ownersInCity >= 50) {
228	            throw new CityAtCapacityException(
229	                "the owner's city already contains 50 or more owners");
230	        }
231	        // Soft warning as the city approaches its hard capacity of 50: flag owners created while
232	        // their city already holds between 40 and 49 owners. Computed on create and returned
233	        // unchanged thereafter.
234	        boolean capacityWarning = ownersInCity >= 40;
235	        String telephone = toE164(ownerFieldsDto.getTelephone());
236	        ownerFieldsDto.setTelephone(telephone);
237	        String email = normalizeEmail(ownerFieldsDto.getEmail());
238	        ownerFieldsDto.setEmail(email);
239	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
240	        String postcode = ownerFieldsDto.getPostcode();
241	        // Deterministic household id: owners with the same normalized last name and postcode
242	        // share it automatically, regardless of creation order. It is no longer created by the
243	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
244	        String householdId = householdId(lastName, postcode);
245	        // The household is keyed on (last name, postcode), so its existing members are the
246	        // existing owners with the same computed household id. Both the duplicate block and the
247	        // household size below key off this value.
248	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
249	            .filter(existing -> !existing.isDeleted())
250	            .filter(existing -> householdId.equals(
251	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
252	            .toList();
253	        // A second owner in an existing household is admitted as a household member; their
254	        // membership level is capped below (level-ceiling rule) rather than rejected.
255	        // Single, consolidated duplicate check: reject only when the new owner's whole derived
256	        // identity key (SHA-256 over telephone|email|soundex(lastName)) equals an existing,
257	        // non-deleted owner's. This single identity key is the only 409; there is no separate
258	        // household-duplicate rejection keyed off the computed householdId.
259	        String newLastName = ownerFieldsDto.getLastName();
260	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, newLastName);
261	        boolean identityInUse = this.clinicService.findAllOwners().stream()
262	            .filter(existing -> !existing.isDeleted())
263	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
264	                existing.getTelephone(), existing.getEmail(), existing.getLastName())));
265	        if (identityInUse) {
266	            throw new DuplicateIdentityException(
267	                "an owner with the same identity key already exists");
268	        }
269	        // Soft match: not a hard duplicate, but shares a household signature with an existing,
270	        // non-deleted owner — the same last-name Soundex and the same postcode while the identity
271	        // key differs (e.g. same last name and postcode but a different telephone). Such an owner
272	        // is still created (201) but flagged as a possible duplicate of the earliest matching owner
273	        // so it can be reviewed rather than rejected.
274	        String newSoundex = IdentityKeyDeriver.soundex(newLastName);
275	        Integer softMatchOf = this.clinicService.findAllOwners().stream()
276	            .filter(existing -> !existing.isDeleted())
277	            .filter(existing -> !identityKey.equals(IdentityKeyDeriver.identityKey(
278	                existing.getTelephone(), existing.getEmail(), existing.getLastName())))
279	            .filter(existing -> newSoundex.equals(IdentityKeyDeriver.soundex(existing.getLastName())))
280	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
281	            .map(Owner::getId)
282	            .min(Integer::compareTo)
283	            .orElse(null);
284	        HttpHeaders headers = new HttpHeaders();
285	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
286	        owner.setRegistrationDate(registrationDate);
287	        owner.setMemberId(deduplicateMemberId(
288	            memberId(owner.getPostcode(), owner.getTelephone(), owner.getLastName(),
289	                owner.getRegistrationDate())));
290	        owner.setHouseholdId(householdId);
291	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
292	        owner.setBulkSignupWarning(bulkSignupWarning);
293	        owner.setCapacityWarning(capacityWarning);
294	        // Household size after this create: existing members plus the owner being created.
295	        owner.setHouseholdSize(householdMembers.size() + 1);
296	        // Level-ceiling: the new owner's membership level cannot exceed one above the current
297	        // maximum level among their existing household members. With no existing member no cap
298	        // applies. The (possibly capped) level is stored so it is returned on create and on read.
299	        int naturalLevel = MembershipPointsDeriver.membershipLevel(
300	            MembershipPointsDeriver.membershipPoints(owner));
301	        int cappedLevel = naturalLevel;
302	        if (!householdMembers.isEmpty()) {
303	            int maxMemberLevel = householdMembers.stream()
304	                .mapToInt(MembershipPointsDeriver::effectiveMembershipLevel)
305	                .max()
306	                .orElseThrow();
307	            cappedLevel = Math.min(naturalLevel, maxMemberLevel + 1);
308	        }
309	        owner.setMembershipLevel(cappedLevel);
310	        // Flag a soft match (same last-name Soundex and postcode as an existing owner, but a
311	        // different identity key) as a possible duplicate of the earliest such owner; a create
312	        // with no soft match is left unflagged.
313	        owner.setPossibleDuplicate(softMatchOf != null);
314	        owner.setPossibleDuplicateOf(softMatchOf);
315	        owner.setDeleted(false);
316	        this.clinicService.saveOwner(owner);
317	        if (idempotencyKey != null) {
318	            idempotentCreates.put(idempotencyKey, owner.getId());
319	        }
320	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
321	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
322	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
323	            ownerDto.getMembershipLevel());
324	        emitOwnerCreatedEvent(owner, ownerDto);
325	        headers.setLocation(UriComponentsBuilder.newInstance()
326	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
327	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
328	    }
