432	    /**
433	     * Returns the {@code Idempotency-Key} header of the current request, or {@code null} when the
434	     * header is absent, blank, or there is no bound request. Read from the request context so the
435	     * generated {@link OwnersApi#addOwner} signature is left untouched.
436	     */
437	    private static String idempotencyKey() {
438	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
439	            return null;
440	        }
441	        String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
442	        return isBlank(key) ? null : key;
443	    }
