445	    /**
446	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
447	     * rolled forward, just as a weekend is, to the next non-holiday business day.
448	     */
449	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
450	        LocalDate.of(2026, 1, 1),
451	        LocalDate.of(2026, 1, 26),
452	        LocalDate.of(2026, 4, 25),
453	        LocalDate.of(2026, 12, 25),
454	        LocalDate.of(2026, 12, 28));
455	
456	    /**
457	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
458	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
459	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
460	     * registration date (whether supplied in the request or defaulted to the server date), so every
461	     * value derived from the registration date sees the adjusted business day.
462	     */
463	    private static LocalDate toBusinessDay(LocalDate date) {
464	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
465	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
466	                || PUBLIC_HOLIDAYS.contains(date)) {
467	            date = date.plusDays(1);
468	        }
469	        return date;
470	    }
