472	    /**
473	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
474	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
475	     * lower-cased so that last names are compared case-insensitively.
476	     */
477	    private static String normalizeHousehold(String value) {
478	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
479	    }
480	
481	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
482	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
483	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
484	
485	    /**
486	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
487	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
488	     * upper-cased, and common street-type abbreviations are expanded token-by-token
489	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
490	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
491	     * used for every address comparison (household-duplicate detection and the shared household id).
492	     */
493	    private static String normalizeAddress(String value) {
494	        if (value == null) {
495	            return "";
496	        }
497	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
498	        if (collapsed.isEmpty()) {
499	            return "";
500	        }
501	        String[] tokens = collapsed.split(" ");
502	        StringBuilder sb = new StringBuilder();
503	        for (int i = 0; i < tokens.length; i++) {
504	            if (i > 0) {
505	                sb.append(' ');
506	            }
507	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
508	        }
509	        return sb.toString();
510	    }
511	
512	    /**
513	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
514	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
515	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
516	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
517	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
518	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
519	     * The resulting {@code address} is the effective value every address reader sees, and is blank
520	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
521	     */
522	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
523	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
524	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
525	        if (!isBlank(line1)) {
526	            ownerFieldsDto.setAddressLine1(line1);
527	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
528	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
529	        } else {
530	            ownerFieldsDto.setAddressLine1(null);
531	            ownerFieldsDto.setAddressLine2(null);
532	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
533	        }
534	    }
535	
536	    /**
537	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
538	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
539	     * deterministic function of the normalized last name and postcode, so every owner that shares
540	     * those values maps to the same identifier regardless of creation order. A {@code null}
541	     * postcode contributes the empty string.
542	     */
543	    private static String householdId(String normalizedLastName, String postcode) {
544	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
545	        return sha256Hex12(key);
546	    }
547	
548	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
549	    private static String sha256Hex12(String s) {
550	        try {
551	            byte[] digest = MessageDigest.getInstance("SHA-256")
552	                .digest(s.getBytes(StandardCharsets.UTF_8));
553	            StringBuilder sb = new StringBuilder(12);
554	            for (int i = 0; i < 6; i++) {
555	                sb.append(String.format("%02x", digest[i]));
556	            }
557	            return sb.toString();
558	        }
559	        catch (NoSuchAlgorithmException e) {
560	            throw new IllegalStateException("SHA-256 not available", e);
561	        }
562	    }
