564	    /**
565	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger as a
566	     * compact JSON object {@code {seq, ownerId, memberId, membershipLevel, event}}. {@code seq}
567	     * is a process-wide monotonically increasing sequence across creates. The event carries the
568	     * owner's current primary identifier via {@link #primaryIdentifier(Owner)} — the memberId — so
569	     * consumers always see the identifier in force.
570	     */
571	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
572	        Map<String, Object> event = new LinkedHashMap<>();
573	        event.put("seq", CREATE_EVENT_SEQ.incrementAndGet());
574	        event.put("ownerId", owner.getId());
575	        event.put("memberId", primaryIdentifier(owner));
576	        event.put("membershipLevel", ownerDto.getMembershipLevel());
577	        event.put("event", OWNER_CREATED_EVENT);
578	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
579	    }
580	
581	    /**
582	     * The owner's current primary identifier carried by structured audit events: the unified
583	     * {@code memberId}.
584	     */
585	    private static String primaryIdentifier(Owner owner) {
586	        return owner.getMemberId();
587	    }
588	
589	    /**
590	     * Builds the {@code memberId} assigned to a new owner, formatted
591	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region code derived from the owner's
592	     * postcode ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}); {@code FY} is the two-digit
593	     * fiscal year of the business-day-adjusted registration date (the fiscal year starts on 1 July);
594	     * {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the owner's normalized
595	     * E.164 telephone concatenated with the last name; and {@code CHK} is a single Luhn check digit
596	     * over the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D4'}). No sequence
597	     * number is used, so the id is a pure function of the owner's own identity fields.
598	     */
599	    private static String memberId(String postcode, String telephone, String lastName,
600	                                   LocalDate registrationDate) {
601	        String region = LocalityDeriver.region(postcode);
602	        String fiscalYear = String.format("%02d",
603	            FiscalYearDeriver.fiscalYear(registrationDate) % 100);
604	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
605	            + (lastName == null ? "" : lastName));
606	        String base = region + fiscalYear + hash8;
607	        return base + CheckDigitDeriver.checkDigit(base);
608	    }
609	
610	    /**
611	     * De-duplicates a computed {@code memberId} against the ids already assigned to existing owners.
612	     * If {@code base} is not currently in use it is returned unchanged; otherwise {@code '-<n>'} is
613	     * appended with the smallest {@code n} of 2 or more that yields an id no existing owner holds
614	     * (e.g. a second collision on {@code 'NSW261A2B3C4D4'} becomes {@code 'NSW261A2B3C4D4-2'}, a
615	     * third {@code 'NSW261A2B3C4D4-3'}, and so on).
616	     */
617	    private String deduplicateMemberId(String base) {
618	        Set<String> existing = this.clinicService.findAllOwners().stream()
619	            .map(Owner::getMemberId)
620	            .filter(id -> id != null)
621	            .collect(Collectors.toSet());
622	        if (!existing.contains(base)) {
623	            return base;
624	        }
625	        int n = 2;
626	        while (existing.contains(base + "-" + n)) {
627	            n++;
628	        }
629	        return base + "-" + n;
630	    }
631	
632	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
633	    private static String sha256Hex8(String s) {
634	        try {
635	            byte[] digest = MessageDigest.getInstance("SHA-256")
636	                .digest(s.getBytes(StandardCharsets.UTF_8));
637	            StringBuilder sb = new StringBuilder(8);
638	            for (int i = 0; i < 4; i++) {
639	                sb.append(String.format("%02X", digest[i]));
640	            }
641	            return sb.toString();
642	        }
643	        catch (NoSuchAlgorithmException e) {
644	            throw new IllegalStateException("SHA-256 not available", e);
645	        }
646	    }
647	
648	    /**
649	     * Counts the existing owners that share the given first name and last name, compared
650	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
651	     * owner currently being created is saved), so it reflects how many namesakes preceded the
652	     * new owner.
653	     */
654	    private int countNamesakes(String firstName, String lastName) {
655	        return (int) this.clinicService.findAllOwners().stream()
656	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
657	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
658	            .count();
659	    }
660	
661	    /**
662	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
663	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
664	     * national one, a single leading {@code '0'} is dropped, and the default country code
665	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
666	     * national number must have the length required by its country code ({@code '+61'} requires 9
667	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
668	     * raised (reported to the client as 400).
669	     */
670	    private static String toE164(String telephone) {
671	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
672	        String digits;
673	        if (cleaned.startsWith("+")) {
674	            digits = cleaned.substring(1);
675	        } else {
676	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
677	            digits = "61" + national;
678	        }
679	        if (!digits.matches("[0-9]{8,15}")) {
680	            throw new InvalidTelephoneException(
681	                "telephone must form a valid E.164 number with 8 to 15 digits");
682	        }
683	        validateNationalLength(digits);
684	        return "+" + digits;
685	    }
686	
687	    /** National-number length required for each supported country code (digits after the code). */
688	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
689	        "61", 9, "1", 10);
690	
691	    /**
692	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
693	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
694	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
695	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
696	     */
697	    private static void validateNationalLength(String digits) {
698	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
699	            String code = entry.getKey();
700	            if (digits.startsWith(code)) {
701	                int nationalLength = digits.length() - code.length();
702	                if (nationalLength != entry.getValue()) {
703	                    throw new InvalidTelephoneException(
704	                        "telephone national number must have " + entry.getValue()
705	                            + " digits for country code +" + code);
706	                }
707	                return;
708	            }
709	        }
710	    }
711	
712	    /**
713	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
714	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
715	     * any 4-digit postcode.
716	     */
717	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
718	        "NSW", new int[] {2000, 2099},
719	        "VIC", new int[] {3000, 3099},
720	        "QLD", new int[] {4000, 4099});
721	
722	    /**
723	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
724	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
725	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
726	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
727	     * no known region accepts any 4-digit postcode. A violation raises an
728	     * {@link InvalidPostcodeException} (reported to the client as 400).
729	     */
730	    private static void validatePostcode(String city, String postcode) {
731	        if (isBlank(postcode)) {
732	            return;
733	        }
734	        if (!postcode.matches("[0-9]{4}")) {
735	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
736	        }
737	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
738	        if (range == null) {
739	            return;
740	        }
741	        int value = Integer.parseInt(postcode);
742	        if (value < range[0] || value > range[1]) {
743	            throw new InvalidPostcodeException(
744	                "postcode is out of range for the owner's city region");
745	        }
746	    }
747	
748	    /**
749	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
750	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
751	     * check).
752	     */
753	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
754	        "mailinator.com", "tempmail.com", "guerrillamail.com");
755	
756	    /**
757	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
758	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
759	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
760	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
761	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
762	     * so it is stored and returned in canonical form.
763	     */
764	    private static String normalizeEmail(String email) {
765	        if (isBlank(email)) {
766	            return null;
767	        }
768	        String trimmed = email.trim();
769	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
770	            throw new InvalidEmailException("email must be a syntactically valid address");
771	        }
772	        String normalized = trimmed.toLowerCase(Locale.ROOT);
773	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
774	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
775	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
776	        }
777	        return normalized;
778	    }
779	}
